window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[300]={"id":"300","numero":300,"titre":"Tumeurs du col utérin et du corps utérin","objectifs":[{"id":"300-1","rang":"B","rubrique":"Col — Épidémiologie","titre":"Connaître l'épidémiologie descriptive en France du cancer du col","contenu":"<div class=\"notion-course\"><p>En France, le cancer du col est le <span>12ème cancer</span> de la femme avec <span>~2 900 nouveaux cas/an</span> et <span>~1 100 décès/an</span> (<span class=\"nc-red nc-bold\">10ème</span> cause de <span>mortalité</span> par cancer chez la femme). C'est en revanche le <span><span class=\"nc-red nc-bold\">4ème</span> cancer</span> de la femme dans le monde, dont <span>85%</span> dans les pays en <span class=\"nc-red_bg nc-bold\">développement</span> — la disparité reflète l'accès au <span>dépistage</span> et à la vaccination <span>HPV</span>.</p><p>L'<span>âge médian</span> au diagnostic est de <span><span class=\"nc-pink nc-bold\">56 ans</span></span> avec un pic d'<span>incidence</span> à <span>45-55 ans</span>. La survie globale à<span> 5 ans</span> dépend du <span>stade</span> : <span>85% au stade IB</span> contre <span>15% au stade IV</span>. L'incidence est <strong>en baisse globale</strong> (grâce au DOCCU) mais paradoxalement <span>en hausse chez les jeunes</span>. <span>40%</span> des femmes éligibles ne sont pas dépistées.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":0},{"id":"300-2","rang":"B","rubrique":"Col — Physiopathologie","titre":"Connaître le rôle de l'infection à virus du papillome humain (HPV) et des autres cofacteurs","contenu":"<div class=\"notion-course\"><p>L'<span>HPV</span> est un <span>virus à ADN</span> dont <span>15 génotypes</span> sont à haut risque oncogène (<span>16, 18, 31, 33, 35, 39, 45, 51, 52, 56, 58, 59, 68, 73, 82</span> — l'<span><span class=\"nc-red nc-bold\">HPV16</span></span> a le plus fort taux de persistance). <span>80%</span> des femmes sexuellement actives sont en contact avec l'<span>HPV</span>, mais seules <span>10%</span> font une infection persistante. Délai contamination → cancer : <span><span class=\"nc-pink\">10 à 15 ans</span></span>.</p><p>L'<span>intégration du génome viral</span> dans la cellule hôte entraîne la surexpression des oncoprotéines <span>E6</span> et <span>E7</span>, qui inactivent respectivement <span>p53</span> et <span>pRB</span> (suppresseurs de tumeur). Résultat : perturbation des mécanismes de réparation de l'ADN et de l'apoptose, prolifération cellulaire rapide.</p><p>L'<span>évolution</span> se fait par étapes successives, lentes :</p><ul><li><span>Infection latente</span> avec <span>koïlocytes</span> (cellules infectées) → élimination spontanée chez <span>90%</span> en <span>1-2 ans</span></li><li><span>Infection productive</span> = <span>CIN1/LSIL</span> (<span>2%</span>) → bas <span>grade</span>, prolifération du 1/3 inférieur du revêtement</li><li><span>Lésion transformante</span> = <span>CIN2-3/<span class=\"nc-red_bg\">HSIL</span></span> (<span>0,5%</span>) → haut <span>grade</span>, prolifération <span>&gt; 1</span>/3</li><li><span>Cancer invasif</span> (<span>0,01%</span>) → franchissement de la membrane basale</li></ul><figure class=\"obj-figure\"><svg class=\"atlas-fig\" viewbox=\"0 0 560 120\" role=\"img\" aria-label=\"Frise de l&#x27;histoire naturelle de l&#x27;infection HPV : infection chez 80 % des femmes exposées, élimination spontanée dans 90 % des cas, persistance dans 10 %, puis CIN1 ou LSIL bas grade 2 %, CIN2-3 ou HSIL haut grade 0,5 %, et cancer invasif 0,01 %, après un délai de 10 à 15 ans.\" style=\"height:auto;display:block;border-radius:8px\"><text class=\"tx-title\" x=\"280\" y=\"14\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Histoire naturelle <span>HPV</span> → CIN → cancer invasif</text><rect class=\"fb-blue\" x=\"6\" y=\"40\" width=\"84\" height=\"42\" rx=\"5\"></rect><text class=\"tx-blue\" x=\"48\" y=\"58\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\">Infection HPV</text><text class=\"tx-blue\" x=\"48\" y=\"73\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\"><span>80 %</span></text><rect class=\"fb-ok\" x=\"99\" y=\"40\" width=\"84\" height=\"42\" rx=\"5\"></rect><text class=\"tx-ok\" x=\"141\" y=\"58\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\"><span>Clairance</span></text><text class=\"tx-ok\" x=\"141\" y=\"73\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\"><span>90 %</span></text><rect class=\"fb-amber\" x=\"192\" y=\"40\" width=\"84\" height=\"42\" rx=\"5\"></rect><text class=\"tx-amber\" x=\"234\" y=\"58\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\">Persistance</text><text class=\"tx-amber\" x=\"234\" y=\"73\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\"><span>10 %</span></text><rect class=\"fb-amber\" x=\"285\" y=\"40\" width=\"84\" height=\"42\" rx=\"5\"></rect><text class=\"tx-amber\" x=\"327\" y=\"58\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\">CIN1 / LSIL</text><text class=\"tx-amber\" x=\"327\" y=\"73\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\"><span>2 %</span></text><rect class=\"fb-red\" x=\"378\" y=\"40\" width=\"84\" height=\"42\" rx=\"5\"></rect><text class=\"tx-red\" x=\"420\" y=\"58\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\">CIN2-3 / HSIL</text><text class=\"tx-red\" x=\"420\" y=\"73\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\"><span>0,5 %</span></text><rect class=\"fb-red\" x=\"471\" y=\"40\" width=\"84\" height=\"42\" rx=\"5\"></rect><text class=\"tx-red\" x=\"513\" y=\"58\" text-anchor=\"middle\" font-size=\"8\" font-weight=\"600\">Cancer invasif</text><text class=\"tx-red\" x=\"513\" y=\"73\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"700\"><span>0,01 %</span></text><line class=\"ln\" x1=\"91\" y1=\"61\" x2=\"96\" y2=\"61\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"99,61 94,58 94,64\"></polygon><line class=\"ln\" x1=\"184\" y1=\"61\" x2=\"189\" y2=\"61\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"192,61 187,58 187,64\"></polygon><line class=\"ln\" x1=\"277\" y1=\"61\" x2=\"282\" y2=\"61\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"285,61 280,58 280,64\"></polygon><line class=\"ln\" x1=\"370\" y1=\"61\" x2=\"375\" y2=\"61\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"378,61 373,58 373,64\"></polygon><line class=\"ln\" x1=\"463\" y1=\"61\" x2=\"468\" y2=\"61\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"471,61 466,58 466,64\"></polygon><line class=\"ln\" x1=\"48\" y1=\"96\" x2=\"505\" y2=\"96\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"513,96 506,93 506,99\"></polygon><text class=\"tx-muted\" x=\"280\" y=\"111\" text-anchor=\"middle\" font-size=\"8.5\">Contamination → cancer :<span> 10-15 ans</span></text></svg><figcaption>Histoire naturelle de l'infection HPV : la grande majorité régresse ; seules les lésions persistantes évoluent vers le cancer, en <span>10 à 15 ans</span>.</figcaption></figure><p>Pour l'<span>adénocarcinome in situ (AIS)</span> :<span> 1%</span> des lésions pré-cancéreuses,<span> 90%</span> <span>HPV</span>-induits (HPV18 ++), survenue <span>25-30 ans</span> (<span><span class=\"nc-pink_bg\">10-20 ans</span></span> avant l'ADK invasif).</p><p><strong>Cofacteurs de persistance / progression</strong> : <span><span class=\"nc-orange_bg\">tabac</span></span> (principal FdR de persistance <span>HPV</span>), <span>contraception orale &gt; 5 ans</span>, <span>co-infection Chlamydia / herpès</span>, <span>déficit immunitaire</span> (++ <span>VIH</span>, transplantés), <span><span class=\"nc-blue_bg\">multiparité</span></span>, <span>précocité du 1er rapport et nombre de partenaires</span> (FdR d'infection initiale). <span class=\"nc-brown_bg\">Bas niveau socio-économique</span> → <span class=\"nc-red nc-bold\">moindre</span> couverture vaccinale et compliance au <span>dépistage</span>.</p><p>Le préservatif ne protège PAS complètement (transmission par contact muqueux et cutanéo-muqueux) — l'<span>HPV</span> n'est pas une IST mais un marqueur d'activité sexuelle.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":1},{"id":"300-3","rang":"B","rubrique":"Col — Définitions","titre":"Connaître les principaux types histologiques de cancer du col utérin","contenu":"<div class=\"notion-course\"><p>La cancérogenèse du col se développe dans la <span><span class=\"nc-red_bg\">zone de transformation</span></span>, à la jonction entre l'<span>épithélium malpighien non kératinisé exocervical</span> et l'<span>épithélium cylindrique <span class=\"nc-blue_bg\">glandulaire</span> endocervical</span>. Cette jonction est <strong><span class=\"nc-pink nc-bold\">hormonodépendante</span></strong> : sa position varie avec l'âge (en ectropion à la puberté/<span>grossesse</span>/THM ; rétractée dans le <span class=\"nc-blue_bg\">canal endocervical</span> après la ménopause). C'est sa régénération active à partir de cellules de réserve bipotentes qui en fait la cible privilégiée de l'<span>HPV</span>.</p><table><thead><tr><th>Type histologique</th><th>Fréquence</th><th>Origine / Précurseur</th><th>Particularités</th></tr></thead><tbody><tr><td><span>Carcinome épidermoïde</span> (malpighien)</td><td><span>80-90%</span></td><td>Épithélium malpighien de l'exocol ; précurseur = <span>CIN/HSIL</span></td><td>Bien identifié au FCU ; meilleur <span>pronostic</span> à <span>stade</span> équivalent</td></tr><tr><td><span>Adénocarcinome</span></td><td><span>10-20%</span> (en hausse)</td><td>Épithélium cylindrique de l'endocol ; précurseur = <span>AIS</span> (adénocarcinome <em>in situ</em>)</td><td>Plus souvent <span>endocervical</span> donc <span>échappe au FCU</span> ; HPV18 ++ ; <span>pronostic</span> plus sombre</td></tr><tr><td><span>Carcinome adénosquameux</span></td><td><span>~5%</span></td><td>Mixte épidermoïde + glandulaire</td><td><span>Pronostic</span> défavorable</td></tr><tr><td><span>Carcinome neuroendocrine</span> (à petites cellules)</td><td><span>&lt; 2%</span></td><td>Cellules neuroendocrines du col</td><td><span>Très agressif</span>, mauvais <span>pronostic</span>, lien HPV18</td></tr><tr><td>Autres <span class=\"nc-red nc-bold\">rares</span></td><td><span>&lt; 1%</span></td><td><span class=\"nc-red nc-bold\">Sarcomes</span>, <span class=\"nc-red nc-bold\">lymphomes</span>, <span class=\"nc-red nc-bold\">mélanomes</span>, métastases</td><td>Hors champ EDN</td></tr></tbody></table><p><strong>Conséquence pratique</strong> : le FCU explore essentiellement la <span class=\"nc-red_bg\">zone de transformation</span> et a une <span><span class=\"nc-red nc-bold\">sensibilité faible</span> (55-77%)</span> pour les lésions glandulaires endocervicales (ADK et <span class=\"nc-red_bg\">AIS</span>). C'est l'un des arguments du passage au <strong>test <span>HPV</span> en <span>1ère ligne</span> après <span>30 ans</span></strong> (cf. obj-4).</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":0},{"id":"300-4","rang":"A","rubrique":"Col — Prévention","titre":"Prévention : connaître l'intérêt de la vaccination","contenu":"<div class=\"notion-course\"><ul><li>La vaccination contre les HPV réduit les <span class=\"nc-blue_bg nc-bold\">infections</span> persistantes et les lésions précancéreuses ; elle est idéalement réalisée avant l’exposition au virus. Elle ne traite pas une infection déjà présente.</li><li><span class=\"nc-green_bg\">Vaccin nonavalent</span> : <span class=\"nc-yellow_bg\">filles et garçons</span> de 11 à 14 ans, schéma à deux doses selon calendrier. En rattrapage, vaccination désormais recommandée et remboursée jusqu’à 26 ans révolus pour les deux sexes, selon le schéma correspondant à l’âge et au terrain.</li><li>Le calendrier vaccinal et les situations d’immunodépression doivent être vérifiés. L’ancienne limite générale de rattrapage à 19 ans ne représente plus la règle actuelle.</li><li>La vaccination ne dispense pas du dépistage du col entre 25 et 65 ans. Les préservatifs réduisent le risque d’IST mais ne protègent pas complètement contre la transmission cutanéo-muqueuse du HPV.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":2},{"id":"300-5","rang":"A","rubrique":"Col — Diagnostic positif","titre":"Prévention : connaître l'intérêt et les modalités du frottis cervico-utérin (FCU) et du test HPV","contenu":"<div class=\"notion-course\"><ul><li>Dépistage chez une personne asymptomatique à risque usuel : de 25 à 29 ans, cytologie avec deux premiers tests normaux à un an d’intervalle, puis trois ans plus tard ; de 30 à 65 ans, test HPV à haut risque tous les cinq ans si négatif.</li><li>À 30 ans, le premier test HPV est réalisé trois ans après la dernière cytologie normale, ou selon l’historique de dépistage. Antécédent de lésion, <span class=\"nc-orange_bg\">immunodépression</span> et suivi après traitement relèvent de parcours spécifiques.</li><li>HPV positif : cytologie réflexe. Cytologie ASC-US ou plus anormale : colposcopie. Cytologie négative : contrôle HPV à un an.</li><li>Au contrôle à un an : HPV encore positif → colposcopie ; HPV négatif → retour au dépistage à cinq ans.</li><li>Une lésion visible, un saignement postcoïtal ou d’autres symptômes imposent une démarche diagnostique ; ne pas attendre le prochain test de dépistage ni se rassurer sur un ancien résultat <span class=\"nc-green nc-bold\">normal</span>.</li></ul><figure class=\"obj-figure\"><svg class=\"atlas-fig\" viewbox=\"0 0 560 262\" role=\"img\" aria-label=\"Arbre decisionnel : conduite a tenir devant un frottis cervico-uterin anormal selon la categorie de Bethesda et l&#x27;age. NILM normal : reprendre le depistage standard. Frottis non satisfaisant : refaire le FCU a 3 a 6 mois. ASC-US : avant 30 ans test HPV reflexe, a partir de 30 ans colposcopie immediate. LSIL bas grade : colposcopie immediate. ASC-H ou HSIL haut grade : colposcopie immediate avec biopsie. AGC ou AIS : colposcopie et curetage endocervical, et exploration de l&#x27;endometre apres 45 ans.\" style=\"height:auto;display:block;border-radius:8px\"><rect class=\"fb-blue\" x=\"150\" y=\"10\" width=\"260\" height=\"32\" rx=\"6\"></rect><text class=\"tx-blue\" x=\"280\" y=\"30\" text-anchor=\"middle\" font-size=\"10\" font-weight=\"600\">FCU + test HPV — résultat ?</text><line class=\"ln\" x1=\"280\" y1=\"42\" x2=\"280\" y2=\"50\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"280,54 276,48 284,48\"></polygon><rect class=\"fb-ok\" x=\"8\" y=\"56\" width=\"150\" height=\"30\" rx=\"5\"></rect><text class=\"tx-ok\" x=\"83\" y=\"75\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">NILM (normal)</text><line class=\"ln\" x1=\"160\" y1=\"71\" x2=\"176\" y2=\"71\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"180,71 174,67.5 174,74.5\"></polygon><rect class=\"fb-ok\" x=\"180\" y=\"56\" width=\"372\" height=\"30\" rx=\"5\"></rect><text class=\"tx-ok\" x=\"366\" y=\"75\" text-anchor=\"middle\" font-size=\"8.5\">Reprendre le <span>dépistage</span> standard</text><rect class=\"fb-grey\" x=\"8\" y=\"90\" width=\"150\" height=\"30\" rx=\"5\"></rect><text class=\"tx-grey\" x=\"83\" y=\"109\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">Non satisfaisant</text><line class=\"ln\" x1=\"160\" y1=\"105\" x2=\"176\" y2=\"105\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"180,105 174,101.5 174,108.5\"></polygon><rect class=\"fb-grey\" x=\"180\" y=\"90\" width=\"372\" height=\"30\" rx=\"5\"></rect><text class=\"tx-grey\" x=\"366\" y=\"109\" text-anchor=\"middle\" font-size=\"8.5\">Refaire le FCU à<span> 3-6 mois</span></text><rect class=\"fb-amber\" x=\"8\" y=\"124\" width=\"150\" height=\"30\" rx=\"5\"></rect><text class=\"tx-amber\" x=\"83\" y=\"143\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">ASC-US</text><line class=\"ln\" x1=\"160\" y1=\"139\" x2=\"176\" y2=\"139\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"180,139 174,135.5 174,142.5\"></polygon><rect class=\"fb-amber\" x=\"180\" y=\"124\" width=\"372\" height=\"30\" rx=\"5\"></rect><text class=\"tx-amber\" x=\"366\" y=\"137\" text-anchor=\"middle\" font-size=\"8\">&lt;<span> 30 ans</span> : test HPV réflexe</text><text class=\"tx-amber\" x=\"366\" y=\"149\" text-anchor=\"middle\" font-size=\"8\"><span>≥ 30 ans</span> : colposcopie immédiate</text><rect class=\"fb-amber\" x=\"8\" y=\"158\" width=\"150\" height=\"30\" rx=\"5\"></rect><text class=\"tx-amber\" x=\"83\" y=\"177\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">LSIL (bas <span>grade</span>)</text><line class=\"ln\" x1=\"160\" y1=\"173\" x2=\"176\" y2=\"173\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"180,173 174,169.5 174,176.5\"></polygon><rect class=\"fb-amber\" x=\"180\" y=\"158\" width=\"372\" height=\"30\" rx=\"5\"></rect><text class=\"tx-amber\" x=\"366\" y=\"177\" text-anchor=\"middle\" font-size=\"8.5\">Colposcopie immédiate</text><rect class=\"fb-red\" x=\"8\" y=\"192\" width=\"150\" height=\"30\" rx=\"5\"></rect><text class=\"tx-red\" x=\"83\" y=\"211\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">ASC-H / HSIL</text><line class=\"ln\" x1=\"160\" y1=\"207\" x2=\"176\" y2=\"207\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"180,207 174,203.5 174,210.5\"></polygon><rect class=\"fb-red\" x=\"180\" y=\"192\" width=\"372\" height=\"30\" rx=\"5\"></rect><text class=\"tx-red\" x=\"366\" y=\"211\" text-anchor=\"middle\" font-size=\"8.5\">Colposcopie immédiate ± <span>biopsie</span></text><rect class=\"fb-red\" x=\"8\" y=\"226\" width=\"150\" height=\"30\" rx=\"5\"></rect><text class=\"tx-red\" x=\"83\" y=\"245\" text-anchor=\"middle\" font-size=\"9\" font-weight=\"600\">AGC / AIS</text><line class=\"ln\" x1=\"160\" y1=\"241\" x2=\"176\" y2=\"241\" stroke-width=\"1.5\"></line><polygon class=\"ah\" points=\"180,241 174,237.5 174,244.5\"></polygon><rect class=\"fb-red\" x=\"180\" y=\"226\" width=\"372\" height=\"30\" rx=\"5\"></rect><text class=\"tx-red\" x=\"366\" y=\"239\" text-anchor=\"middle\" font-size=\"8\">Colposcopie + <span>curetage</span> endocervical</text><text class=\"tx-red\" x=\"366\" y=\"251\" text-anchor=\"middle\" font-size=\"8\">si &gt;<span> 45 ans</span> : explorer l'endomètre</text></svg><figcaption>Synthèse de la conduite à tenir selon la catégorie de Bethesda et l'âge — seule la biopsie sous colposcopie confirme le diagnostic, jamais la cytologie.</figcaption></figure></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":5},{"id":"300-6","rang":"A","rubrique":"Col — Diagnostic positif","titre":"Connaître les circonstances de découverte du cancer du col","contenu":"<div class=\"notion-course\"><p><span <span=\"\">&gt;2</span> grandes situations à connaître :</p><ol><li><strong>Découverte au DOCCU chez une femme asymptomatique</strong> : c'est le mode le plus fréquent pour les stades précoces. Anomalie cytologique au FCU ou test <span>HPV</span>+ → colposcopie + biopsies ciblées → diagnostic histologique. <span>L'objectif du DOCCU est précisément de capter les lésions à ce stade pré-symptomatique.</span></li><li><strong>Découverte clinique chez une femme symptomatique</strong> : signale en règle un cancer déjà avancé, le col étant longtemps asymptomatique.</li></ol><p><strong>Tableau clinique évocateur</strong> :</p><table><thead><tr><th>Signe</th><th>Valeur sémiologique</th></tr></thead><tbody><tr><td><span><span class=\"nc-blue_bg\">Métrorragies</span> provoquées</span> (post-coïtales ++)</td><td><span>Signe d'appel majeur</span> — toute métrorragie provoquée chez une femme en âge d'activité génitale doit faire évoquer un cancer du col jusqu'à preuve du contraire</td></tr><tr><td><span><span class=\"nc-blue_bg\">Métrorragies spontanées</span></span> (intermenstruelles ou post-ménopausiques)</td><td>Plus tardives, parfois fétides si surinfection <span>tumorale</span></td></tr><tr><td><span>Leucorrhées</span> séropurulentes ou sanglantes</td><td>Forme évoluée (<span>nécrose</span> <span>tumorale</span>)</td></tr><tr><td><span>Douleurs pelviennes</span> ou <span>lombo-radiculalgies</span></td><td><span>Stade très évolué</span> — sciatique tronquée = <span>envahissement</span> des paramètres et compression du nerf sciatique</td></tr><tr><td>Signes <span>urinaires</span> (dysurie, pollakiurie, <span>hématurie</span>)</td><td><span>Envahissement</span> vésical (FIGO IV)</td></tr><tr><td>Signes <span>rectaux</span> (ténesme, <span>rectorragies</span>, faux besoins)</td><td><span>Envahissement</span> rectal (FIGO IV)</td></tr><tr><td><span><span class=\"nc-red_bg\">Fistule</span></span> vésico-vaginale ou recto-vaginale</td><td><span>Stade terminal</span></td></tr><tr><td><span>AEG</span>, <span>œdèmes</span> des MI</td><td><span>Stade</span> métastatique ou compression ilio-cave</td></tr></tbody></table><p><strong>Découverte fortuite</strong> : sur pièce d'<span>hystérectomie</span> réalisée pour une autre indication (myomes, prolapsus…) ou sur pièce de <span><span class=\"nc-pink nc-bold\">conisation</span></span> faite pour une dysplasie. Imposera une réintervention si marges non saines.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":0},{"id":"300-7","rang":"A","rubrique":"Col — Diagnostic positif","titre":"Savoir diagnostiquer cliniquement du cancer du col utérin","contenu":"<div class=\"notion-course\"><p>Devant une suspicion clinique (métrorragies provoquées ++) ou anomalie au DOCCU, l'examen du col se fait en consultation, idéalement par un gynécologue, en plusieurs temps.</p><p><strong>1. <span class=\"nc-blue nc-bold\">Examen au spéculum</span></strong> — temps clé : il permet la <span>visualisation directe de la tumeur</span> dans la grande majorité des cas (sauf endocervicale invisible). On décrit :</p><ul><li>Forme : <span>bourgeonnante/exophytique</span> (la plus fréquente), <span>ulcérée</span>, <span>ulcéro-bourgeonnante</span> ou <span>infiltrante</span> (col en barillet, induré)</li><li>Taille (en mm/cm), siège (lèvre antérieure/postérieure, circulaire)</li><li>Saignement spontané ou au contact ++</li><li>Friabilité, <span>nécrose</span>, leucorrhées associées</li></ul><p><strong>2. Touchers pelviens</strong> (<span>TV</span> + TR combiné) — apprécient :</p><ul><li>Volume du col, consistance (induration <span>tumorale</span> dure et irrégulière)</li><li>Mobilité du col par rapport aux organes voisins</li><li><span>Infiltration des paramètres</span> au TR (clé pour la <span>stadification</span> clinique FIGO) — paramètres souples → IB / IIA ; paramètres infiltrés → IIB+ ; paramètres « bloqués » contre la paroi pelvienne → IIIB</li><li>Atteinte du <span>1/3 inférieur du vagin</span> au <span>TV</span> (IIIA)</li></ul><p><strong>3. <span>Biopsie</span> à la pince</strong> — <span>temps diagnostique</span>. Si <span>lésion</span> visible au spéculum → biopsie directe à la pince <strong>sans <span class=\"nc-blue nc-bold\">colposcopie</span></strong> (la lésion est visible à l'œil nu). Si col cliniquement <span class=\"nc-green nc-bold\">normal</span> mais cytologie/<span>HPV</span> <span class=\"nc-red nc-bold\">anormal</span> → biopsies sous <span class=\"nc-blue nc-bold\">colposcopie</span> ± <span>conisation diagnostique</span> à visée diagnostique et thérapeutique. <strong>L'<span>histologie</span> est la seule à poser le diagnostic.</strong></p><p><strong>4. Examen général</strong> — palpation aires ganglionnaires (sus-claviculaires gauches = Troisier, inguinales), examen des seins, palpation abdominale (ascite, HMG), recherche d'<span>œdèmes</span> des MI.</p><p>L'examen <strong>sous anesthésie générale</strong> (EUS / EMS) est parfois nécessaire si la patiente est douloureuse ou si l'examen en consultation est incomplet — il permet d'affiner la <span>stadification</span> clinique avant les imageries.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":0},{"id":"300-8","rang":"B","rubrique":"Col — Examens complémentaires","titre":"Connaître les examens complémentaires du cancer du col utérin (IRM)","contenu":"<div class=\"notion-course\"><p>Une fois le diagnostic histologique posé (biopsies cervicales sous guidage colposcopique, ou pièce de <span class=\"nc-pink nc-bold\">conisation</span>), le <span>bilan d'extension</span> repose sur l'<span><span class=\"nc-yellow_bg\">IRM abdomino-pelvienne</span></span> (référence : T2 sans saturation graisse + T1 + T2 FATSAT, des pédicules rénaux à la symphyse pubienne) pour mesurer la taille <span>tumorale</span>, l'extension paramétriale/vésicale/rectale et l'atteinte ganglionnaire pelvienne et lombo-aortique. Le <span>TEP-TDM 18-FDG</span> est proposé pour le bilan à distance si tumeur <span>&gt; 2 cm</span> (GOB) ou <span>&gt; 4 cm</span> (HAS) = FIGO ≥ IB2. <span><span class=\"nc-blue_bg\">Cystoscopie</span>/<span class=\"nc-blue_bg\">rectoscopie</span></span> uniquement si doute <span>IRM</span>. Bio : <span>NFS</span>, <span>ionogramme</span>, BH, BR, <span>sérologie</span> <span>HIV</span> ; marqueurs <span><span class=\"nc-pink nc-bold\">SCC</span></span> (épidermoïde) ou <span><span class=\"nc-pink nc-bold\">Ca-125</span></span> (ADK, <span>suivi</span> non diagnostic).</p><table><thead><tr><th><span>Stade</span> FIGO</th><th>Extension</th></tr></thead><tbody><tr><td><span>I</span></td><td>Strictement <strong>confiné au col</strong>. IA : microscopique (<span>≤ 5 mm</span>) — IB : clinique, <span>≤ 4 cm</span> max</td></tr><tr><td><span>II</span></td><td>Extension au-delà du col, <strong>sans atteinte de la paroi pelvienne ni du 1/3 inférieur du vagin</strong>. IIA : 2/3 supérieurs du vagin — IIB : extension paramétriale</td></tr><tr><td><span>III</span></td><td>Extension à la <strong>paroi pelvienne</strong> ou au <strong>1/3 inférieur du vagin</strong> ou atteinte ganglionnaire pelvienne (IIIC1) / lombo-aortique (IIIC2)</td></tr><tr><td><span>IV</span></td><td>Invasion <span>vessie, rectum</span> (IVA) ou <span>métastases à distance</span> (IVB)</td></tr></tbody></table><p><span <span=\"\">&gt;3</span> grands groupes pronostiques : <strong>précoce</strong> (FIGO ≤ IB2, faible volume), <strong>localement avancé</strong> (IB3 à IVA, gros volume ou paramètres ou ganglionnaire), <strong>métastatique</strong> (IVB). Facteurs pronostiques : type histologique, volume <span>tumoral</span>, <span>emboles lymphovasculaires</span>, <span>envahissement</span> ganglionnaire, <span>stade</span>.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/cervical-carcinoma-1","label":"Radiopaedia : Cervical carcinoma"},{"href":"https://radiopaedia.org/articles/cervix","label":"Radiopaedia : Cervix"},{"href":"https://radiopaedia.org/articles/cervical-polyp","label":"Radiopaedia : Cervical polyp"}]},{"id":"300-9","rang":"B","rubrique":"Corps — Épidémiologie","titre":"Connaître l'épidémiologie descriptive en France du cancer de l'endomètre","contenu":"<div class=\"notion-course\"><p>Le cancer du corps utérin est le <span><span class=\"nc-red nc-bold\">4ème</span> cancer</span> de la femme et le <strong>1er cancer gynécologique en France</strong> : <span>~8 224 nouveaux cas/an</span>, <span>incidence</span> stable sur 2 décennies. <span>~2 415 décès/an</span> (<span class=\"nc-red nc-bold\">6ème</span> cancer en termes de décès).</p><p>C'est un cancer de la <span>femme ménopausée</span> (âge moyen <span><span class=\"nc-pink nc-bold\">68 ans</span></span>). Le diagnostic est fait à un <span>stade</span> <strong>précoce dans <span>70%</span></strong> des cas → bon <span>pronostic</span> : survie globale à<span> 5 ans</span> <span>90%</span>, survie relative tous stades confondus <span>75%</span>.</p><p><span>Aucun test de dépistage de masse n'est recommandé</span> (contrairement au cancer du col). Le diagnostic repose sur la <strong>vigilance clinique devant des métrorragies post-ménopausiques</strong> (cf. obj-11).</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":0},{"id":"300-10","rang":"A","rubrique":"Corps — Étiologie","titre":"Epidémiologie analytique : citer les facteurs de risque du cancer du corps utérin","contenu":"<div class=\"notion-course\"><p>Le cancer de <span class=\"nc-green nc-bold\">l'endomètre</span> est un cancer <strong>hormonodépendant</strong>, dont la quasi-totalité des <span>facteurs de risque</span> relève de l'<span>hyperoestrogénie</span> non compensée par la progestérone. Mnémo classique : <strong>« VOTT Direct à Gauche »</strong> (Vie génitale, <span>Obésité</span>, THM, <span class=\"nc-pink_bg\">Tamoxifène</span>, Diabète, <span>Génétique</span>).</p><table><thead><tr><th>Catégorie</th><th>Facteurs de risque</th></tr></thead><tbody><tr><td><span>Vie génitale</span></td><td><ul><li><span><span class=\"nc-blue_bg\">Nulliparité</span></span></li><li><span>Puberté précoce</span></li><li><span>Ménopause tardive</span> avec péri-ménopause longue</li><li><span>SOPK</span></li></ul></td></tr><tr><td><span>Obésité</span></td><td><span>Obésité</span> <span>androïde</span> : <span class=\"nc-red nc-bold\">aromatisation</span> périphérique de l'androsténedione → ↗ œstrogènes endogènes. <span>40%</span> des cancers de l'endomètre y sont liés.</td></tr><tr><td><span>THM sans progestatif</span></td><td><span>RR 4-5</span> chez les femmes non hystérectomisées. Risque normalisé si progestatif associé <span>≥ 10</span>-12 j/cycle.</td></tr><tr><td><span><span class=\"nc-pink_bg\">Tamoxifène</span></span></td><td><span>RR 2-7</span>. <span>Bénéfices &gt; risques</span> dans la prévention du cancer du sein. <span>Surveillance</span> gynéco systématique pendant le traitement.</td></tr><tr><td><span>Diabète</span></td><td><span>DT2</span> : <span>RR 2,8</span>. <strong>Pas le tabac</strong> (contrairement au col).</td></tr><tr><td><span>Génétique</span></td><td><span><span class=\"nc-red_bg\">Syndrome de Lynch</span></span> : <span>60% de risque</span> <span>vs</span> <span>1,5%</span> en population générale, survenue <span>15 ans plus tôt</span>. À évoquer si <span>5%</span> des cas (jeune femme, ATCD familiaux côlon/endomètre).</td></tr><tr><td><span><span class=\"nc-brown_bg\">HTA</span></span></td><td>FdR indépendant (souvent associé au tableau métabolique)</td></tr></tbody></table><p>Facteurs <strong>protecteurs</strong> : <span>multiparité ≥ 4 grossesses</span>, <span>COP</span> (RR 0,5, protection <span>10 ans</span> après arrêt), <span><span class=\"nc-green_bg\">DIU au lévonorgestrel</span> 52 mg</span>, <span><span class=\"nc-green_bg\">puberté tardive</span> ≥ 15 ans</span>.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":2},{"id":"300-11","rang":"B","rubrique":"Corps — Définitions","titre":"Connaître les deux types histologiques de cancer de l'endomètre les plus fréquents","contenu":"<div class=\"notion-course\"><p>Anatomie rappel : de l'intérieur vers l'extérieur, la paroi utérine comprend <span class=\"nc-green nc-bold\">l'</span><span><span class=\"nc-green nc-bold\">endomètre</span></span> (épithélium glandulaire cylindrique sur chorion conjonctif, hormonosensible aux œstrogènes/progestérone), le <span><span class=\"nc-green_bg\">myomètre</span></span> (faisceaux entrecroisés de cellules musculaires lisses) et l'<span>adventice/séreuse</span>. Les cancers du corps utérin sont dominés par les <span>adénocarcinomes endométriaux</span> (<span>90%</span>, d'origine épithéliale glandulaire). Les autres entités (sarcomes, <span class=\"nc-red_bg\">carcinosarcomes</span>, TNE) sont rares et hors champ EDN.</p><p>Les adénocarcinomes se répartissent en <strong>2 types pronostiques radicalement différents</strong>, à connaître impérativement car ils conditionnent la prise en charge.</p><table><thead><tr><th>Critère</th><th>Type 1 (endométrioïde)</th><th>Type 2 (non endométrioïde)</th></tr></thead><tbody><tr><td>Fréquence</td><td><span>80%</span></td><td><span>20%</span></td></tr><tr><td>Hormonodépendance</td><td><strong>Oui</strong> — sur hyperoestrogénie</td><td><strong>Non</strong> hormonodépendant</td></tr><tr><td><span>Lésion</span> pré-cancéreuse</td><td><span>Hyperplasie glandulaire atypique</span></td><td><span><span class=\"nc-orange_bg\">Carcinome </span><em><span class=\"nc-orange_bg\">in situ</span></em></span></td></tr><tr><td><span>Histologie</span></td><td>Endométrioïde (bien différencié à peu différencié)</td><td>Séreux papillaire, à cellules claires (<span>toujours haut grade</span>), mucineux, mixtes, indifférenciés, <span>carcinome</span> neuroendocrine à petites cellules</td></tr><tr><td>Âge moyen</td><td><span>~65 ans</span></td><td><span>~70 ans</span></td></tr><tr><td><span>Pronostic</span></td><td><strong>Bon</strong></td><td><span>Mauvais</span></td></tr></tbody></table><p><strong>Grading histologique</strong> : <span <span=\"\">&gt;3</span> grades de <span>différenciation</span> selon la surface du contingent solide (<span>&lt; 5%</span>, <span>6-50%</span>, <span>&gt; 50%</span>) et les atypies nucléaires — G1 bien différencié, G2 moyen, G3 peu différencié. <strong><span>Classification</span> moléculaire FIGO 2023</strong> (à connaître) : <span>POLE muté</span> (excellent <span>pronostic</span>), <span>MMR-déficient</span> (Lynch — pronostic intermédiaire, immunothérapie), <span>p53 anormal</span> (mauvais pronostic, équivalent type 2), <span>NSMP</span> (no specific molecular profile, intermédiaire) — guide les décisions thérapeutiques.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":4},{"id":"300-12","rang":"A","rubrique":"Corps — Diagnostic positif","titre":"Connaître les circonstances de découverte du cancer du corps utérin","contenu":"<div class=\"notion-course\"><p>Les <span>métrorragies post-ménopausiques</span> sont le principal mode de révélation (~<span>90%</span> des cas) — toute métrorragie chez une femme ménopausée doit faire <strong>évoquer un cancer de l'endomètre jusqu'à preuve du contraire</strong>. <span class=\"nc-red nc-bold\">Plus la patiente est âgée</span>, plus le risque est élevé.</p><table><thead><tr><th>Signe</th><th>Contexte / Valeur</th></tr></thead><tbody><tr><td><span>Métrorragies post-ménopausiques</span></td><td>~<span>90%</span> des cas — <strong>signe d'appel cardinal</strong></td></tr><tr><td><span>Ménométrorragies</span> chez la femme non ménopausée</td><td><span>20-30%</span> — plus difficile à interpréter (DD : myome, hyperplasie sans atypie, polype)</td></tr><tr><td><span><span class=\"nc-blue_bg\">Hydrorrhée</span></span></td><td>Écoulement séreux clair, abondant — fréquent</td></tr><tr><td><span><span class=\"nc-blue_bg\">Pyorrhée</span></span></td><td>Rare, mais chez la femme âgée doit <strong>toujours faire évoquer un cancer</strong> de l'endomètre</td></tr><tr><td>Signes de <span>compression</span> (dysurie, <span>constipation</span>)</td><td>Utérus volumineux, <span><span class=\"nc-red nc-bold\">stade</span></span><span class=\"nc-red nc-bold\"> avancé</span></td></tr><tr><td><span>Découverte fortuite</span></td><td>Sur pièce d'hystérectomie pour autre indication, ou écho/<span>IRM</span> pour autre motif révélant un endomètre suspect</td></tr></tbody></table><p><span>Vigilance Lynch</span> : devant des métrorragies chez une femme jeune (&lt; 50 ans) avec ATCD familiaux côlon/endomètre/ovaire, évoquer systématiquement un <span class=\"nc-red_bg\">syndrome de Lynch</span>.</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":1},{"id":"300-13","rang":"A","rubrique":"Corps — Diagnostic positif","titre":"Savoir diagnostiquer cliniquement du cancer du corps utérin","contenu":"<div class=\"notion-course\"><p>Devant des métrorragies post-ménopausiques (ou ménométrorragies suspectes), démarche diagnostique <strong>en 2 temps</strong> :</p><ol><li><span>Échographie pelvienne</span> en <span>1ère intention</span> (<strong>voie endo-vaginale</strong> plus précise que sus-pubienne). Mesure de l'<strong>épaisseur endométriale</strong> :<ul><li><span><span class=\"nc-green nc-bold\">&lt; 4 mm</span></span> chez femme ménopausée : probabilité de cancer très faible, <strong><span class=\"nc-green nc-bold\">VPN</span> excellente</strong></li><li><span><span class=\"nc-red nc-bold\">≥ 5 mm</span></span> chez patiente ménopausée : <span>anormal</span> → exploration histologique systématique</li></ul></li><li><span>Prélèvement pour analyse histologique</span> (= diagnostic de certitude) :<ul><li><span>Biopsie d'endomètre à la <span class=\"nc-green_bg\">pipelle de Cornier</span></span> en <span>1ère intention</span> (aspirative, en consultation, sans anesthésie). Nécessite une bonne perméabilité <span class=\"nc-red nc-bold\">cervicale</span>. <span>Un résultat négatif n'élimine pas un cancer</span> (<span>biopsie</span> aveugle, <span>lésion</span> focale possible manquée) → si forte suspicion, <span class=\"nc-blue_bg\">hystéroscopie</span> systématique.</li><li><span><span class=\"nc-blue_bg\">Hystéroscopie</span> diagnostique + biopsies dirigées</span> si pipelle négative/ininterprétable, ou si tumeur volumineuse/friable, ou écho très suspecte. <strong>CI à l'<span class=\"nc-red nc-bold\">hystéro-résection</span> diagnostique</strong> qui dissémine les cellules tumorales — biopsies sous contrôle visuel uniquement.</li><li><span>Curetage biopsique</span> pendant l'<span class=\"nc-blue_bg\">hystéroscopie</span> si tumeur friable (biopsies non dirigées mais plus volumineuses).</li></ul></li></ol><p><strong>Examen clinique</strong> : spéculum (saignements faible abondance par l'orifice cervical → confirme l'origine endo-utérine), <span>TV</span> peu contributif (utérus parfois gros et globuleux mais souvent atrophique). Toujours rechercher un <span>cancer du sein synchrone</span> (association fréquente, <span>dépistage</span> <span>mammographie</span>/examen clinique des seins) et évaluer l'opérabilité (<span>score G8</span>, ASA) car <span>terrain</span> souvent difficile (âgé, <span>HTA</span>, obèse, diabétique).</p></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":1},{"id":"300-14","rang":"B","rubrique":"Corps — Examens complémentaires","titre":"Connaître la stratégie d'exploration par imagerie d'une tumeur du corps utérin","contenu":"<div class=\"notion-course\"><ul><li>Métrorragies postménopausiques : examen gynécologique et échographie endovaginale avec mesure et description de l’endomètre ; prélèvement endométrial selon le contexte.</li><li>Un endomètre fin (repère ≤ 4 mm dans une situation appropriée) réduit la probabilité de cancer, mais n’annule pas le besoin d’exploration si saignement persistant/récidivant, facteurs de risque ou image mal analysable.</li><li>Endomètre épaissi, aspect suspect, prélèvement insuffisant ou symptômes persistants : histologie, souvent par <span class=\"nc-blue_bg\">hystéroscopie</span> avec biopsie ciblée selon l’équipe. Une biopsie aveugle négative ne suffit pas si la suspicion reste forte.</li><li>Après confirmation histologique : IRM pelvienne pour extension locale et examens d’extension adaptés au risque, puis discussion en RCP. La TDM thoraco-abdomino-pelvienne recherche les extensions à distance selon indication.</li><li>La classification historique en types I/II et les stades purement anatomiques ont des limites : l’histologie, le grade et le profil moléculaire participent désormais à la stratification thérapeutique.</li></ul></div><details><summary>Sources et compléments</summary><p>Cours personnel Notion, objectifs LiSA et compléments des sources ci-dessous. Les actualisations sont distinguées du contenu des figures historiques. Révision éditoriale : 15 octobre 2026.</p><ul><li><a href=\"https://cego-obgyn.fr/deuxieme-cycle/\" target=\"_blank\" rel=\"noopener noreferrer\">Collège CNGOF–CEGO · Référentiel, 6e édition 2024</a></li><li><a href=\"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/\" target=\"_blank\" rel=\"noopener noreferrer\">INCa · Dépistage du col de l’utérus</a></li><li><a href=\"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans\" target=\"_blank\" rel=\"noopener noreferrer\">Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025</a></li><li><a href=\"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNGOF · Cytologie cervicale anormale, actualisation 2025</a></li></ul></details>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/uterus","label":"Radiopaedia : Uterus"},{"href":"https://radiopaedia.org/articles/endometrial-polyp","label":"Radiopaedia : Endometrial polyp"},{"href":"https://radiopaedia.org/articles/endometrial-carcinoma","label":"Radiopaedia : Endometrial carcinoma"}]}],"astuces":[],"strategie":{"principes":"<p><em>Stratégie de prise en charge à compléter — non disponible dans la source GitHub pour cet item.</em></p>"},"cards":[{"i":"283107e135ad","n":300,"o":"300-10","u":"Corps — Étiologie","t":"Epidémiologie analytique : citer les facteurs de risque du cancer du corps utérin","q":"Quel est le mécanisme principal sous-jacent à la quasi-totalité des facteurs de risque du cancer de l'endomètre ?","a":"<div class=\"notion-course\"><p>Le mécanisme principal est l'<strong>hyperœstrogénie non compensée</strong> par la progestérone.</p></div>"},{"i":"304bc2fdbc6d","n":300,"o":"300-10","u":"Corps — Étiologie","t":"Epidémiologie analytique : citer les facteurs de risque du cancer du corps utérin","q":"Quels sont les facteurs de risque métaboliques et génétiques pour le cancer de l'endomètre ?","a":"<div class=\"notion-course\"><ul><li>Le <strong>Diabète de type 2</strong> (risque relatif de 2,8).</li><li>Le <strong><span class=\"nc-red_bg\">Syndrome de Lynch</span></strong>, qui augmente le risque à 60% (contre 1,5% dans la population générale) et se manifeste 15 ans plus tôt. Il est à évoquer si 5% des cas (jeune femme, antécédents familiaux de cancer colorectal/endomètre).</li><li>L'<strong>Hypertension Artérielle (<span class=\"nc-brown_bg\">HTA</span>)</strong>, facteur de risque indépendant souvent associé au tableau métabolique.</li></ul></div>"},{"i":"3b17fa68c135","n":300,"o":"300-10","u":"Corps — Étiologie","t":"Epidémiologie analytique : citer les facteurs de risque du cancer du corps utérin","q":"Quels sont les facteurs protecteurs du cancer de l'endomètre ?","a":"<div class=\"notion-course\"><ul><li>La <strong>multiparité</strong> (≥ 4 grossesses).</li><li>Les <strong>contraceptifs oraux combinés (COP)</strong>, qui offrent une protection pendant 10 ans après l'arrêt (risque relatif de 0,5).</li><li>Le <strong>Dispositif Intra-Utérin (DIU) au lévonorgestrel 52 mg</strong>.</li><li>La <strong><span class=\"nc-green_bg\">puberté tardive</span></strong> (≥ 15 ans).</li></ul></div>"},{"i":"5707b3cc6282","n":300,"o":"300-10","u":"Corps — Étiologie","t":"Epidémiologie analytique : citer les facteurs de risque du cancer du corps utérin","q":"Quels sont les facteurs de risque liés à la vie génitale et hormonale pour le cancer de l'endomètre ?","a":"<div class=\"notion-course\"><ul><li>La <strong>nulliparité</strong>.</li><li>La <strong>puberté précoce</strong>.</li><li>La <strong>ménopause tardive</strong> avec une péri-ménopause longue.</li><li>Le <strong>Syndrome des Ovaires Polykystiques</strong> (SOPK).</li><li>L'<strong>obésité androïde</strong>, qui entraîne une augmentation des œstrogènes endogènes et est liée à 40% des cancers de l'endomètre.</li><li>Un <strong>Traitement Hormonal de la Ménopause (THM) sans progestatif</strong> chez les femmes non hystérectomisées (risque relatif de 4-5).</li><li>Le <strong><span class=\"nc-pink_bg\">Tamoxifène</span></strong> (risque relatif de 2-7).</li></ul></div>"},{"i":"30bd85a4ed20","n":300,"o":"300-13","u":"Corps — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du corps utérin","q":"Pourquoi la biopsie d'endomètre à la pipelle de Cornier, même négative, n'élimine-t-elle pas totalement le diagnostic de cancer de l'endomètre ?","a":"<div class=\"notion-course\"><p>Un résultat négatif n'élimine pas totalement le cancer car il s'agit d'une <strong>biopsie aveugle</strong>, risquant de manquer une <strong>lésion focale</strong>.</p></div>"},{"i":"a05697ed54ec","n":300,"o":"300-13","u":"Corps — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du corps utérin","q":"Dans quel cas doit-on systématiquement réaliser une hystéroscopie diagnostique avec biopsies dirigées lors de la recherche d'un cancer du corps utérin ?","a":"<div class=\"notion-course\"><p>Une <span class=\"nc-blue_bg\">hystéroscopie</span> diagnostique avec biopsies dirigées est systématique si le résultat de la pipelle est <strong>négatif ou ininterprétable</strong> malgré une forte suspicion clinique, ou si l'échographie est très suspecte, ou en présence d'une tumeur volumineuse ou friable.</p></div>"},{"i":"b18b2d5d9ea2","n":300,"o":"300-13","u":"Corps — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du corps utérin","q":"Quelle est la méthode de prélèvement histologique de première intention pour confirmer le diagnostic de cancer du corps utérin ?","a":"<div class=\"notion-course\"><p>La méthode de première intention est la <strong>biopsie d'endomètre à la <span class=\"nc-green_bg\">pipelle de Cornier</span></strong>. Elle est aspirative, réalisée en consultation et ne nécessite pas d'anesthésie.</p></div>"},{"i":"c628c5bd9f96","n":300,"o":"300-13","u":"Corps — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du corps utérin","q":"Quelle est la première étape de la démarche diagnostique devant des métrorragies post-ménopausiques ou ménométrorragies suspectes évoquant un cancer du corps utérin ?","a":"<div class=\"notion-course\"><p>La première étape est la réalisation d'une <strong><span class=\"nc-blue_bg\">échographie pelvienne</span> par voie endo-vaginale</strong>.</p></div>"},{"i":"dbfd967aac13","n":300,"o":"300-13","u":"Corps — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du corps utérin","q":"Quelle épaisseur endométriale à l'échographie est considérée comme anormale chez une femme ménopausée et justifie une exploration histologique systématique pour un possible cancer du corps utérin ?","a":"<div class=\"notion-course\"><p>Une épaisseur endométriale <strong>supérieure ou égale à 5 mm</strong> chez une patiente ménopausée est considérée comme anormale et impose une exploration histologique systématique.</p></div>"},{"i":"ebdaccf747ca","n":300,"o":"300-13","u":"Corps — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du corps utérin","q":"Quels sont les éléments clés à rechercher lors de l'examen clinique d'une patiente suspectée de cancer du corps utérin ?","a":"<div class=\"notion-course\"><p>L'examen clinique comprend un examen au <strong>spéculum</strong> pour objectiver des saignements de faible abondance provenant de l'orifice cervical. Il faut également rechercher un <strong>cancer du sein synchrone</strong> et évaluer l'opérabilité de la patiente (scores G8, ASA), compte tenu du terrain souvent difficile (âgé, HTA, obèse, diabétique).</p></div>"},{"i":"4aff81e1ee6a","n":300,"o":"300-4","u":"Col — Prévention","t":"Prévention : connaître l'intérêt de la vaccination","q":"Quel est le nom du vaccin HPV actuellement utilisé en prévention des tumeurs du col utérin et des infections liées au HPV, et quels sous-types de HPV cible-t-il ?","a":"<div class=\"notion-course\"><ul><li>La vaccination contre les HPV réduit les <span class=\"nc-blue_bg nc-bold\">infections</span> persistantes et les lésions précancéreuses ; elle est idéalement réalisée avant l’exposition au virus. Elle ne traite pas une infection déjà présente.</li><li><span class=\"nc-green_bg\">Vaccin nonavalent</span> : <span class=\"nc-yellow_bg\">filles et garçons</span> de 11 à 14 ans, schéma à deux doses selon calendrier. En rattrapage, vaccination désormais recommandée et remboursée jusqu’à 26 ans révolus pour les deux sexes, selon le schéma correspondant à l’âge et au terrain.</li><li>Le calendrier vaccinal et les situations d’immunodépression doivent être vérifiés. L’ancienne limite générale de rattrapage à 19 ans ne représente plus la règle actuelle.</li><li>La vaccination ne dispense pas du dépistage du col entre 25 et 65 ans. Les préservatifs réduisent le risque d’IST mais ne protègent pas complètement contre la transmission cutanéo-muqueuse du HPV.</li></ul></div>"},{"i":"8c24297cfe92","n":300,"o":"300-4","u":"Col — Prévention","t":"Prévention : connaître l'intérêt de la vaccination","q":"Quels sont les bénéfices de la vaccination HPV et son rôle par rapport au dépistage des lésions du col utérin ?","a":"<div class=\"notion-course\"><ul><li>La vaccination contre les HPV réduit les <span class=\"nc-blue_bg nc-bold\">infections</span> persistantes et les lésions précancéreuses ; elle est idéalement réalisée avant l’exposition au virus. Elle ne traite pas une infection déjà présente.</li><li><span class=\"nc-green_bg\">Vaccin nonavalent</span> : <span class=\"nc-yellow_bg\">filles et garçons</span> de 11 à 14 ans, schéma à deux doses selon calendrier. En rattrapage, vaccination désormais recommandée et remboursée jusqu’à 26 ans révolus pour les deux sexes, selon le schéma correspondant à l’âge et au terrain.</li><li>Le calendrier vaccinal et les situations d’immunodépression doivent être vérifiés. L’ancienne limite générale de rattrapage à 19 ans ne représente plus la règle actuelle.</li><li>La vaccination ne dispense pas du dépistage du col entre 25 et 65 ans. Les préservatifs réduisent le risque d’IST mais ne protègent pas complètement contre la transmission cutanéo-muqueuse du HPV.</li></ul></div>"},{"i":"b5b176ad521b","n":300,"o":"300-4","u":"Col — Prévention","t":"Prévention : connaître l'intérêt de la vaccination","q":"Quelles sont les principales indications du calendrier vaccinal français pour la vaccination HPV chez les jeunes, et leurs schémas vaccinaux respectifs ?","a":"<div class=\"notion-course\"><ul><li>La vaccination contre les HPV réduit les <span class=\"nc-blue_bg nc-bold\">infections</span> persistantes et les lésions précancéreuses ; elle est idéalement réalisée avant l’exposition au virus. Elle ne traite pas une infection déjà présente.</li><li><span class=\"nc-green_bg\">Vaccin nonavalent</span> : <span class=\"nc-yellow_bg\">filles et garçons</span> de 11 à 14 ans, schéma à deux doses selon calendrier. En rattrapage, vaccination désormais recommandée et remboursée jusqu’à 26 ans révolus pour les deux sexes, selon le schéma correspondant à l’âge et au terrain.</li><li>Le calendrier vaccinal et les situations d’immunodépression doivent être vérifiés. L’ancienne limite générale de rattrapage à 19 ans ne représente plus la règle actuelle.</li><li>La vaccination ne dispense pas du dépistage du col entre 25 et 65 ans. Les préservatifs réduisent le risque d’IST mais ne protègent pas complètement contre la transmission cutanéo-muqueuse du HPV.</li></ul></div>"},{"i":"bde6195b6d0f","n":300,"o":"300-4","u":"Col — Prévention","t":"Prévention : connaître l'intérêt de la vaccination","q":"Quels sont les effets indésirables connus de la vaccination HPV et les idées fausses courantes à son sujet ?","a":"<div class=\"notion-course\"><ul><li>La vaccination contre les HPV réduit les <span class=\"nc-blue_bg nc-bold\">infections</span> persistantes et les lésions précancéreuses ; elle est idéalement réalisée avant l’exposition au virus. Elle ne traite pas une infection déjà présente.</li><li><span class=\"nc-green_bg\">Vaccin nonavalent</span> : <span class=\"nc-yellow_bg\">filles et garçons</span> de 11 à 14 ans, schéma à deux doses selon calendrier. En rattrapage, vaccination désormais recommandée et remboursée jusqu’à 26 ans révolus pour les deux sexes, selon le schéma correspondant à l’âge et au terrain.</li><li>Le calendrier vaccinal et les situations d’immunodépression doivent être vérifiés. L’ancienne limite générale de rattrapage à 19 ans ne représente plus la règle actuelle.</li><li>La vaccination ne dispense pas du dépistage du col entre 25 et 65 ans. Les préservatifs réduisent le risque d’IST mais ne protègent pas complètement contre la transmission cutanéo-muqueuse du HPV.</li></ul></div>"},{"i":"f2d104f5894e","n":300,"o":"300-4","u":"Col — Prévention","t":"Prévention : connaître l'intérêt de la vaccination","q":"Quelles sont les indications spécifiques pour la vaccination HPV chez les groupes à risque, comme les HSH et les immunodéprimés ?","a":"<div class=\"notion-course\"><ul><li>La vaccination contre les HPV réduit les <span class=\"nc-blue_bg nc-bold\">infections</span> persistantes et les lésions précancéreuses ; elle est idéalement réalisée avant l’exposition au virus. Elle ne traite pas une infection déjà présente.</li><li><span class=\"nc-green_bg\">Vaccin nonavalent</span> : <span class=\"nc-yellow_bg\">filles et garçons</span> de 11 à 14 ans, schéma à deux doses selon calendrier. En rattrapage, vaccination désormais recommandée et remboursée jusqu’à 26 ans révolus pour les deux sexes, selon le schéma correspondant à l’âge et au terrain.</li><li>Le calendrier vaccinal et les situations d’immunodépression doivent être vérifiés. L’ancienne limite générale de rattrapage à 19 ans ne représente plus la règle actuelle.</li><li>La vaccination ne dispense pas du dépistage du col entre 25 et 65 ans. Les préservatifs réduisent le risque d’IST mais ne protègent pas complètement contre la transmission cutanéo-muqueuse du HPV.</li></ul></div>"},{"i":"1a3606057e7b","n":300,"o":"300-5","u":"Col — Diagnostic positif","t":"Prévention : connaître l'intérêt et les modalités du frottis cervico-utérin (FCU) et du test HPV","q":"Quelles sont les modalités de dépistage du cancer du col utérin et leur rythme en fonction de l'âge dans le cadre du DOCCU ?","a":"<div class=\"notion-course\"><ul><li>Dépistage chez une personne asymptomatique à risque usuel : de 25 à 29 ans, cytologie avec deux premiers tests normaux à un an d’intervalle, puis trois ans plus tard ; de 30 à 65 ans, test HPV à haut risque tous les cinq ans si négatif.</li><li>À 30 ans, le premier test HPV est réalisé trois ans après la dernière cytologie normale, ou selon l’historique de dépistage. Antécédent de lésion, <span class=\"nc-orange_bg\">immunodépression</span> et suivi après traitement relèvent de parcours spécifiques.</li><li>HPV positif : cytologie réflexe. Cytologie ASC-US ou plus anormale : colposcopie. Cytologie négative : contrôle HPV à un an.</li><li>Au contrôle à un an : HPV encore positif → colposcopie ; HPV négatif → retour au dépistage à cinq ans.</li><li>Une lésion visible, un saignement postcoïtal ou d’autres symptômes imposent une démarche diagnostique ; ne pas attendre le prochain test de dépistage ni se rassurer sur un ancien résultat <span class=\"nc-green nc-bold\">normal</span>.</li></ul></div>"},{"i":"4bd51477bbbb","n":300,"o":"300-5","u":"Col — Diagnostic positif","t":"Prévention : connaître l'intérêt et les modalités du frottis cervico-utérin (FCU) et du test HPV","q":"Quel est l'intérêt et la particularité du test HPV par PCR par rapport au FCU en termes de sensibilité et spécificité ?","a":"<div class=\"notion-course\"><ul><li>Dépistage chez une personne asymptomatique à risque usuel : de 25 à 29 ans, cytologie avec deux premiers tests normaux à un an d’intervalle, puis trois ans plus tard ; de 30 à 65 ans, test HPV à haut risque tous les cinq ans si négatif.</li><li>À 30 ans, le premier test HPV est réalisé trois ans après la dernière cytologie normale, ou selon l’historique de dépistage. Antécédent de lésion, <span class=\"nc-orange_bg\">immunodépression</span> et suivi après traitement relèvent de parcours spécifiques.</li><li>HPV positif : cytologie réflexe. Cytologie ASC-US ou plus anormale : colposcopie. Cytologie négative : contrôle HPV à un an.</li><li>Au contrôle à un an : HPV encore positif → colposcopie ; HPV négatif → retour au dépistage à cinq ans.</li><li>Une lésion visible, un saignement postcoïtal ou d’autres symptômes imposent une démarche diagnostique ; ne pas attendre le prochain test de dépistage ni se rassurer sur un ancien résultat <span class=\"nc-green nc-bold\">normal</span>.</li></ul></div>"},{"i":"7fc81fbaf3f2","n":300,"o":"300-5","u":"Col — Diagnostic positif","t":"Prévention : connaître l'intérêt et les modalités du frottis cervico-utérin (FCU) et du test HPV","q":"Quelles sont les conditions optimales pour la réalisation d'un frottis cervico-utérin (FCU) afin d'en assurer la validité ?","a":"<div class=\"notion-course\"><ul><li>Dépistage chez une personne asymptomatique à risque usuel : de 25 à 29 ans, cytologie avec deux premiers tests normaux à un an d’intervalle, puis trois ans plus tard ; de 30 à 65 ans, test HPV à haut risque tous les cinq ans si négatif.</li><li>À 30 ans, le premier test HPV est réalisé trois ans après la dernière cytologie normale, ou selon l’historique de dépistage. Antécédent de lésion, <span class=\"nc-orange_bg\">immunodépression</span> et suivi après traitement relèvent de parcours spécifiques.</li><li>HPV positif : cytologie réflexe. Cytologie ASC-US ou plus anormale : colposcopie. Cytologie négative : contrôle HPV à un an.</li><li>Au contrôle à un an : HPV encore positif → colposcopie ; HPV négatif → retour au dépistage à cinq ans.</li><li>Une lésion visible, un saignement postcoïtal ou d’autres symptômes imposent une démarche diagnostique ; ne pas attendre le prochain test de dépistage ni se rassurer sur un ancien résultat <span class=\"nc-green nc-bold\">normal</span>.</li></ul></div>"},{"i":"a8ff23a4d185","n":300,"o":"300-5","u":"Col — Diagnostic positif","t":"Prévention : connaître l'intérêt et les modalités du frottis cervico-utérin (FCU) et du test HPV","q":"Dans quelles situations spécifiques un dépistage individuel du cancer du col utérin est-il recommandé en dehors du DOCCU ?","a":"<div class=\"notion-course\"><ul><li>Dépistage chez une personne asymptomatique à risque usuel : de 25 à 29 ans, cytologie avec deux premiers tests normaux à un an d’intervalle, puis trois ans plus tard ; de 30 à 65 ans, test HPV à haut risque tous les cinq ans si négatif.</li><li>À 30 ans, le premier test HPV est réalisé trois ans après la dernière cytologie normale, ou selon l’historique de dépistage. Antécédent de lésion, <span class=\"nc-orange_bg\">immunodépression</span> et suivi après traitement relèvent de parcours spécifiques.</li><li>HPV positif : cytologie réflexe. Cytologie ASC-US ou plus anormale : colposcopie. Cytologie négative : contrôle HPV à un an.</li><li>Au contrôle à un an : HPV encore positif → colposcopie ; HPV négatif → retour au dépistage à cinq ans.</li><li>Une lésion visible, un saignement postcoïtal ou d’autres symptômes imposent une démarche diagnostique ; ne pas attendre le prochain test de dépistage ni se rassurer sur un ancien résultat <span class=\"nc-green nc-bold\">normal</span>.</li></ul></div>"},{"i":"cab2d8c981a8","n":300,"o":"300-5","u":"Col — Diagnostic positif","t":"Prévention : connaître l'intérêt et les modalités du frottis cervico-utérin (FCU) et du test HPV","q":"Quel est l'objectif principal du dépistage organisé du cancer du col utérin (DOCCU) en France et quelles populations cible-t-il ?","a":"<div class=\"notion-course\"><ul><li>Dépistage chez une personne asymptomatique à risque usuel : de 25 à 29 ans, cytologie avec deux premiers tests normaux à un an d’intervalle, puis trois ans plus tard ; de 30 à 65 ans, test HPV à haut risque tous les cinq ans si négatif.</li><li>À 30 ans, le premier test HPV est réalisé trois ans après la dernière cytologie normale, ou selon l’historique de dépistage. Antécédent de lésion, <span class=\"nc-orange_bg\">immunodépression</span> et suivi après traitement relèvent de parcours spécifiques.</li><li>HPV positif : cytologie réflexe. Cytologie ASC-US ou plus anormale : colposcopie. Cytologie négative : contrôle HPV à un an.</li><li>Au contrôle à un an : HPV encore positif → colposcopie ; HPV négatif → retour au dépistage à cinq ans.</li><li>Une lésion visible, un saignement postcoïtal ou d’autres symptômes imposent une démarche diagnostique ; ne pas attendre le prochain test de dépistage ni se rassurer sur un ancien résultat <span class=\"nc-green nc-bold\">normal</span>.</li></ul></div>"},{"i":"117cb812b7a9","n":300,"o":"300-6","u":"Col — Diagnostic positif","t":"Connaître les circonstances de découverte du cancer du col","q":"Quels sont les signes cliniques indiquant un stade très avancé ou métastatique du cancer du col utérin, et que signifient-ils ?","a":"<div class=\"notion-course\"><ul><li>Des <strong>douleurs pelviennes ou lombo-radiculalgies</strong> (notamment une sciatique tronquée), signe d'un envahissement des paramètres.</li><li>Des <strong>signes urinaires</strong> (dysurie, pollakiurie, hématurie), indiquant un envahissement vésical (FIGO IV).</li><li>Des <strong>signes rectaux</strong> (ténesme, rectorragies, faux besoins), traduisant un envahissement rectal (FIGO IV).</li><li>La formation de <strong>fistules vésico-vaginales ou recto-vaginales</strong>, signe d'un stade terminal.</li><li>Une <strong>Altération de l'État Général (AEG)</strong> ou des <strong>œdèmes des membres inférieurs</strong> signent un stade métastatique ou une compression ilio-cave.</li></ul></div>"},{"i":"90276cf5f452","n":300,"o":"300-6","u":"Col — Diagnostic positif","t":"Connaître les circonstances de découverte du cancer du col","q":"Quels sont les principaux signes cliniques évocateurs d'un cancer du col utérin qui signalent généralement un stade déjà avancé ?","a":"<div class=\"notion-course\"><ul><li>Les <strong>métrorragies provoquées</strong> (post-coïtales +++), signe d'appel majeur.</li><li>Les <strong><span class=\"nc-blue_bg\">métrorragies spontanées</span></strong> (intermenstruelles ou post-ménopausiques), parfois fétides.</li><li>Des <strong>leucorrhées séropurulentes ou sanglantes</strong>, témoignant d'une forme évoluée avec nécrose tumorale.</li></ul></div>"},{"i":"935ff3ea6f36","n":300,"o":"300-6","u":"Col — Diagnostic positif","t":"Connaître les circonstances de découverte du cancer du col","q":"Dans quelles circonstances peut-on découvrir fortuitement un cancer du col utérin ?","a":"<div class=\"notion-course\"><p>La découverte fortuite d'un cancer du col utérin peut survenir :</p><ul><li>Sur une <strong>pièce d'hystérectomie</strong> réalisée pour une autre indication (par exemple, des myomes ou un prolapsus).</li><li>Sur une <strong>pièce de conisation</strong> effectuée pour une dysplasie. Dans ce cas, une réintervention sera nécessaire si les marges ne sont pas saines.</li></ul></div>"},{"i":"981c063e28a6","n":300,"o":"300-6","u":"Col — Diagnostic positif","t":"Connaître les circonstances de découverte du cancer du col","q":"Quelle est la circonstance de découverte la plus fréquente du cancer du col utérin à un stade précoce, et comment est-elle menée ?","a":"<div class=\"notion-course\"><p>La circonstance de découverte la plus fréquente pour les stades précoces est le <strong><span class=\"nc-red nc-bold\">Dépistage</span> Organisé du Cancer du Col de l'Utérus (DOCCU)</strong> chez une femme asymptomatique. Elle repose sur la détection d'une anomalie cytologique au <span class=\"nc-blue_bg\">Frottis Cervico-Utérin</span> (FCU) ou d'un test HPV positif, conduisant à une <strong>colposcopie avec biopsies ciblées</strong> pour un diagnostic histologique.</p></div>"},{"i":"61612ff504e6","n":300,"o":"300-7","u":"Col — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du col utérin","q":"Comment doit être réalisée l'évaluation diagnostique initiale du cancer du col utérin en présence d'une suspicion clinique (métrorragies provoquées) ou d'une anomalie au DOCCU ?","a":"<div class=\"notion-course\"><p>L'évaluation diagnostique initiale doit être réalisée en consultation, idéalement par un gynécologue, et comprend plusieurs étapes :</p><ul><li>Un <strong><span class=\"nc-blue nc-bold\">examen au spéculum</span></strong>.</li><li>Des <strong>touchers pelviens</strong> (toucher vaginal et toucher rectal combinés).</li><li>Une <strong>biopsie à la pince</strong>.</li><li>Un <strong>examen général</strong>.</li></ul></div>"},{"i":"70f9c51e65e8","n":300,"o":"300-7","u":"Col — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du col utérin","q":"Que permettent d'apprécier les touchers pelviens (toucher vaginal et toucher rectal combinés) dans le cadre du diagnostic clinique d'un cancer du col utérin ?","a":"<div class=\"notion-course\"><p>Les touchers pelviens permettent d'apprécier :</p><ul><li>Le <strong>volume du col</strong> et sa <strong>consistance</strong> (recherche d'une induration tumorale, dure et irrégulière).</li><li>La <strong>mobilité du col</strong> par rapport aux organes voisins.</li><li>L'<strong>infiltration des paramètres</strong> au toucher rectal, essentielle pour la stadification clinique FIGO :<ul><li>Paramètres souples → <strong>IB / IIA</strong>.</li><li>Paramètres infiltrés → <strong>IIB+</strong>.</li><li>Paramètres « bloqués » contre la paroi pelvienne → <strong>IIIB</strong>.</li></ul></li><li>L'<strong>atteinte du tiers inférieur du vagin</strong> au toucher vaginal (Stade <strong>IIIA</strong>).</li></ul></div>"},{"i":"a4b38bccf384","n":300,"o":"300-7","u":"Col — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du col utérin","q":"Quelle est l'importance de la biopsie dans le diagnostic du cancer du col utérin, et quand est-elle réalisée sous colposcopie ?","a":"<div class=\"notion-course\"><p>La <strong>biopsie à la pince</strong> est le <strong>temps diagnostique</strong> fondamental car l'<strong>histologie</strong> est la seule à poser le diagnostic définitif.</p><ul><li>Si la lésion est visible au spéculum, la <strong>biopsie est réalisée directement à la pince</strong>.</li><li>Si le col est cliniquement <span class=\"nc-green nc-bold\">normal</span> mais qu'il existe une cytologie ou un test HPV <span class=\"nc-red nc-bold\">anormal</span>, les <strong>biopsies sont réalisées sous colposcopie</strong>, éventuellement associées à une conisation diagnostique à visée diagnostique et thérapeutique.</li></ul></div>"},{"i":"cae0b65a041d","n":300,"o":"300-7","u":"Col — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du col utérin","q":"Quel est l'intérêt de l'examen sous anesthésie générale (EUS/EMS) dans le contexte du diagnostic du cancer du col utérin ?","a":"<div class=\"notion-course\"><p>L'examen sous anesthésie générale (EUS/EMS) est parfois nécessaire si la patiente est douloureuse ou si l'examen en consultation est incomplet. Il permet d'<strong>affiner la stadification clinique</strong> avant les examens d'imagerie, notamment l'appréciation de l'extension tumorale.</p></div>"},{"i":"ce7c7655c862","n":300,"o":"300-7","u":"Col — Diagnostic positif","t":"Savoir diagnostiquer cliniquement du cancer du col utérin","q":"Quels éléments clés évalue-t-on lors de l'examen au spéculum devant une suspicion de cancer du col utérin ?","a":"<div class=\"notion-course\"><p>L'<span class=\"nc-blue nc-bold\">examen au spéculum</span> est un temps essentiel qui permet de visualiser directement la tumeur dans la majorité des cas. Il faut décrire :</p><ul><li>La <strong>forme de la lésion</strong> : <strong>bourgeonnante/exophytique</strong> (la plus fréquente), ulcérée, ulcéro-bourgeonnante ou infiltrante (col en barillet, induré).</li><li>La <strong>taille</strong> (en mm/cm) et le <strong>siège</strong> (lèvre antérieure/postérieure, circulaire).</li><li>Un éventuel <strong>saignement spontané ou au contact</strong>.</li><li>La <strong>friabilité</strong>, la <strong>nécrose</strong> et la présence de <strong>leucorrhées associées</strong>.</li></ul></div>"},{"i":"1a8626bf1cc4","n":300,"o":"300-1","u":"Col — Épidémiologie","t":"Connaître l'épidémiologie descriptive en France du cancer du col","q":"Que retenir concernant l'épidémiologie descriptive en France du cancer du col ?","a":"<div class=\"notion-course\"><p>En France, le cancer du col est le <span>12ème cancer</span> de la femme avec <span>~2 900 nouveaux cas/an</span> et <span>~1 100 décès/an</span> (<span class=\"nc-red nc-bold\">10ème</span> cause de <span>mortalité</span> par cancer chez la femme). C'est en revanche le <span><span class=\"nc-red nc-bold\">4ème</span> cancer</span> de la femme dans le monde, dont <span>85%</span> dans les pays en <span class=\"nc-red_bg nc-bold\">développement</span> — la disparité reflète l'accès au <span>dépistage</span> et à la vaccination <span>HPV</span>.</p><p>L'<span>âge médian</span> au diagnostic est de <span><span class=\"nc-pink nc-bold\">56 ans</span></span> avec un pic d'<span>incidence</span> à <span>45-55 ans</span>. La survie globale à<span> 5 ans</span> dépend du <span>stade</span> : <span>85% au stade IB</span> contre <span>15% au stade IV</span>. L'incidence est <strong>en baisse globale</strong> (grâce au DOCCU) mais paradoxalement <span>en hausse chez les jeunes</span>. <span>40%</span> des femmes éligibles ne sont pas dépistées.</p></div>"},{"i":"02d97abdb125","n":300,"o":"300-2","u":"Col — Physiopathologie","t":"Connaître le rôle de l'infection à virus du papillome humain (HPV) et des autres cofacteurs","q":"Que retenir concernant le rôle de l'infection à virus du papillome humain (HPV) et des autres cofacteurs ?","a":"<div class=\"notion-course\"><p>L'<span>HPV</span> est un <span>virus à ADN</span> dont <span>15 génotypes</span> sont à haut risque oncogène (<span>16, 18, 31, 33, 35, 39, 45, 51, 52, 56, 58, 59, 68, 73, 82</span> — l'<span><span class=\"nc-red nc-bold\">HPV16</span></span> a le plus fort taux de persistance). <span>80%</span> des femmes sexuellement actives sont en contact avec l'<span>HPV</span>, mais seules <span>10%</span> font une infection persistante. Délai contamination → cancer : <span><span class=\"nc-pink\">10 à 15 ans</span></span>.</p><p>L'<span>intégration du génome viral</span> dans la cellule hôte entraîne la surexpression des oncoprotéines <span>E6</span> et <span>E7</span>, qui inactivent respectivement <span>p53</span> et <span>pRB</span> (suppresseurs de tumeur). Résultat : perturbation des mécanismes de réparation de l'ADN et de l'apoptose, prolifération cellulaire rapide.</p><p>L'<span>évolution</span> se fait par étapes successives, lentes :</p><ul><li><span>Infection latente</span> avec <span>koïlocytes</span> (cellules infectées) → élimination spontanée chez <span>90%</span> en <span>1-2 ans</span></li><li><span>Infection productive</span> = <span>CIN1/LSIL</span> (<span>2%</span>) → bas <span>grade</span>, prolifération du 1/3 inférieur du revêtement</li><li><span>Lésion transformante</span> = <span>CIN2-3/<span class=\"nc-red_bg\">HSIL</span></span> (<span>0,5%</span>) → haut <span>grade</span>, prolifération <span>&gt; 1</span>/3</li><li><span>Cancer invasif</span> (<span>0,01%</span>) → franchissement de la membrane basale</li></ul><p>Pour l'<span>adénocarcinome in situ (AIS)</span> :<span> 1%</span> des lésions pré-cancéreuses,<span> 90%</span> <span>HPV</span>-induits (HPV18 ++), survenue <span>25-30 ans</span> (<span><span class=\"nc-pink_bg\">10-20 ans</span></span> avant l'ADK invasif).</p><p><strong>Cofacteurs de persistance / progression</strong> : <span><span class=\"nc-orange_bg\">tabac</span></span> (principal FdR de persistance <span>HPV</span>), <span>contraception orale &gt; 5 ans</span>, <span>co-infection Chlamydia / herpès</span>, <span>déficit immunitaire</span> (++ <span>VIH</span>, transplantés), <span><span class=\"nc-blue_bg\">multiparité</span></span>, <span>précocité du 1er rapport et nombre de partenaires</span> (FdR d'infection initiale). <span class=\"nc-brown_bg\">Bas niveau socio-économique</span> → <span class=\"nc-red nc-bold\">moindre</span> couverture vaccinale et compliance au <span>dépistage</span>.</p><p>Le préservatif ne protège PAS complètement (transmission par contact muqueux et cutanéo-muqueux) — l'<span>HPV</span> n'est pas une IST mais un marqueur d'activité sexuelle.</p></div>"},{"i":"fae38a674b66","n":300,"o":"300-3","u":"Col — Définitions","t":"Connaître les principaux types histologiques de cancer du col utérin","q":"Que retenir concernant les principaux types histologiques de cancer du col utérin ?","a":"<div class=\"notion-course\"><p>La cancérogenèse du col se développe dans la <span><span class=\"nc-red_bg\">zone de transformation</span></span>, à la jonction entre l'<span>épithélium malpighien non kératinisé exocervical</span> et l'<span>épithélium cylindrique <span class=\"nc-blue_bg\">glandulaire</span> endocervical</span>. Cette jonction est <strong><span class=\"nc-pink nc-bold\">hormonodépendante</span></strong> : sa position varie avec l'âge (en ectropion à la puberté/<span>grossesse</span>/THM ; rétractée dans le <span class=\"nc-blue_bg\">canal endocervical</span> après la ménopause). C'est sa régénération active à partir de cellules de réserve bipotentes qui en fait la cible privilégiée de l'<span>HPV</span>.</p><table><thead><tr><th>Type histologique</th><th>Fréquence</th><th>Origine / Précurseur</th><th>Particularités</th></tr></thead><tbody><tr><td><span>Carcinome épidermoïde</span> (malpighien)</td><td><span>80-90%</span></td><td>Épithélium malpighien de l'exocol ; précurseur = <span>CIN/HSIL</span></td><td>Bien identifié au FCU ; meilleur <span>pronostic</span> à <span>stade</span> équivalent</td></tr><tr><td><span>Adénocarcinome</span></td><td><span>10-20%</span> (en hausse)</td><td>Épithélium cylindrique de l'endocol ; précurseur = <span>AIS</span> (adénocarcinome <em>in situ</em>)</td><td>Plus souvent <span>endocervical</span> donc <span>échappe au FCU</span> ; HPV18 ++ ; <span>pronostic</span> plus sombre</td></tr><tr><td><span>Carcinome adénosquameux</span></td><td><span>~5%</span></td><td>Mixte épidermoïde + glandulaire</td><td><span>Pronostic</span> défavorable</td></tr><tr><td><span>Carcinome neuroendocrine</span> (à petites cellules)</td><td><span>&lt; 2%</span></td><td>Cellules neuroendocrines du col</td><td><span>Très agressif</span>, mauvais <span>pronostic</span>, lien HPV18</td></tr><tr><td>Autres <span class=\"nc-red nc-bold\">rares</span></td><td><span>&lt; 1%</span></td><td><span class=\"nc-red nc-bold\">Sarcomes</span>, <span class=\"nc-red nc-bold\">lymphomes</span>, <span class=\"nc-red nc-bold\">mélanomes</span>, métastases</td><td>Hors champ EDN</td></tr></tbody></table><p><strong>Conséquence pratique</strong> : le FCU explore essentiellement la <span class=\"nc-red_bg\">zone de transformation</span> et a une <span><span class=\"nc-red nc-bold\">sensibilité faible</span> (55-77%)</span> pour les lésions glandulaires endocervicales (ADK et <span class=\"nc-red_bg\">AIS</span>). C'est l'un des arguments du passage au <strong>test <span>HPV</span> en <span>1ère ligne</span> après <span>30 ans</span></strong> (cf. obj-4).</p></div>"},{"i":"ad37b0211eaf","n":300,"o":"300-8","u":"Col — Examens complémentaires","t":"Connaître les examens complémentaires du cancer du col utérin (IRM)","q":"Que retenir concernant les examens complémentaires du cancer du col utérin (IRM) ?","a":"<div class=\"notion-course\"><p>Une fois le diagnostic histologique posé (biopsies cervicales sous guidage colposcopique, ou pièce de <span class=\"nc-pink nc-bold\">conisation</span>), le <span>bilan d'extension</span> repose sur l'<span><span class=\"nc-yellow_bg\">IRM abdomino-pelvienne</span></span> (référence : T2 sans saturation graisse + T1 + T2 FATSAT, des pédicules rénaux à la symphyse pubienne) pour mesurer la taille <span>tumorale</span>, l'extension paramétriale/vésicale/rectale et l'atteinte ganglionnaire pelvienne et lombo-aortique. Le <span>TEP-TDM 18-FDG</span> est proposé pour le bilan à distance si tumeur <span>&gt; 2 cm</span> (GOB) ou <span>&gt; 4 cm</span> (HAS) = FIGO ≥ IB2. <span><span class=\"nc-blue_bg\">Cystoscopie</span>/<span class=\"nc-blue_bg\">rectoscopie</span></span> uniquement si doute <span>IRM</span>. Bio : <span>NFS</span>, <span>ionogramme</span>, BH, BR, <span>sérologie</span> <span>HIV</span> ; marqueurs <span><span class=\"nc-pink nc-bold\">SCC</span></span> (épidermoïde) ou <span><span class=\"nc-pink nc-bold\">Ca-125</span></span> (ADK, <span>suivi</span> non diagnostic).</p><table><thead><tr><th><span>Stade</span> FIGO</th><th>Extension</th></tr></thead><tbody><tr><td><span>I</span></td><td>Strictement <strong>confiné au col</strong>. IA : microscopique (<span>≤ 5 mm</span>) — IB : clinique, <span>≤ 4 cm</span> max</td></tr><tr><td><span>II</span></td><td>Extension au-delà du col, <strong>sans atteinte de la paroi pelvienne ni du 1/3 inférieur du vagin</strong>. IIA : 2/3 supérieurs du vagin — IIB : extension paramétriale</td></tr><tr><td><span>III</span></td><td>Extension à la <strong>paroi pelvienne</strong> ou au <strong>1/3 inférieur du vagin</strong> ou atteinte ganglionnaire pelvienne (IIIC1) / lombo-aortique (IIIC2)</td></tr><tr><td><span>IV</span></td><td>Invasion <span>vessie, rectum</span> (IVA) ou <span>métastases à distance</span> (IVB)</td></tr></tbody></table><p><span <span=\"\">&gt;3</span> grands groupes pronostiques : <strong>précoce</strong> (FIGO ≤ IB2, faible volume), <strong>localement avancé</strong> (IB3 à IVA, gros volume ou paramètres ou ganglionnaire), <strong>métastatique</strong> (IVB). Facteurs pronostiques : type histologique, volume <span>tumoral</span>, <span>emboles lymphovasculaires</span>, <span>envahissement</span> ganglionnaire, <span>stade</span>.</p></div>"},{"i":"f3998b8bd0ba","n":300,"o":"300-9","u":"Corps — Épidémiologie","t":"Connaître l'épidémiologie descriptive en France du cancer de l'endomètre","q":"Que retenir concernant l'épidémiologie descriptive en France du cancer de l'endomètre ?","a":"<div class=\"notion-course\"><p>Le cancer du corps utérin est le <span><span class=\"nc-red nc-bold\">4ème</span> cancer</span> de la femme et le <strong>1er cancer gynécologique en France</strong> : <span>~8 224 nouveaux cas/an</span>, <span>incidence</span> stable sur 2 décennies. <span>~2 415 décès/an</span> (<span class=\"nc-red nc-bold\">6ème</span> cancer en termes de décès).</p><p>C'est un cancer de la <span>femme ménopausée</span> (âge moyen <span><span class=\"nc-pink nc-bold\">68 ans</span></span>). Le diagnostic est fait à un <span>stade</span> <strong>précoce dans <span>70%</span></strong> des cas → bon <span>pronostic</span> : survie globale à<span> 5 ans</span> <span>90%</span>, survie relative tous stades confondus <span>75%</span>.</p><p><span>Aucun test de dépistage de masse n'est recommandé</span> (contrairement au cancer du col). Le diagnostic repose sur la <strong>vigilance clinique devant des métrorragies post-ménopausiques</strong> (cf. obj-11).</p></div>"},{"i":"4ca513e21e06","n":300,"o":"300-11","u":"Corps — Définitions","t":"Connaître les deux types histologiques de cancer de l'endomètre les plus fréquents","q":"Que retenir concernant les deux types histologiques de cancer de l'endomètre les plus fréquents ?","a":"<div class=\"notion-course\"><p>Anatomie rappel : de l'intérieur vers l'extérieur, la paroi utérine comprend <span class=\"nc-green nc-bold\">l'</span><span><span class=\"nc-green nc-bold\">endomètre</span></span> (épithélium glandulaire cylindrique sur chorion conjonctif, hormonosensible aux œstrogènes/progestérone), le <span><span class=\"nc-green_bg\">myomètre</span></span> (faisceaux entrecroisés de cellules musculaires lisses) et l'<span>adventice/séreuse</span>. Les cancers du corps utérin sont dominés par les <span>adénocarcinomes endométriaux</span> (<span>90%</span>, d'origine épithéliale glandulaire). Les autres entités (sarcomes, <span class=\"nc-red_bg\">carcinosarcomes</span>, TNE) sont rares et hors champ EDN.</p><p>Les adénocarcinomes se répartissent en <strong>2 types pronostiques radicalement différents</strong>, à connaître impérativement car ils conditionnent la prise en charge.</p><table><thead><tr><th>Critère</th><th>Type 1 (endométrioïde)</th><th>Type 2 (non endométrioïde)</th></tr></thead><tbody><tr><td>Fréquence</td><td><span>80%</span></td><td><span>20%</span></td></tr><tr><td>Hormonodépendance</td><td><strong>Oui</strong> — sur hyperoestrogénie</td><td><strong>Non</strong> hormonodépendant</td></tr><tr><td><span>Lésion</span> pré-cancéreuse</td><td><span>Hyperplasie glandulaire atypique</span></td><td><span><span class=\"nc-orange_bg\">Carcinome </span><em><span class=\"nc-orange_bg\">in situ</span></em></span></td></tr><tr><td><span>Histologie</span></td><td>Endométrioïde (bien différencié à peu différencié)</td><td>Séreux papillaire, à cellules claires (<span>toujours haut grade</span>), mucineux, mixtes, indifférenciés, <span>carcinome</span> neuroendocrine à petites cellules</td></tr><tr><td>Âge moyen</td><td><span>~65 ans</span></td><td><span>~70 ans</span></td></tr><tr><td><span>Pronostic</span></td><td><strong>Bon</strong></td><td><span>Mauvais</span></td></tr></tbody></table><p><strong>Grading histologique</strong> : <span <span=\"\">&gt;3</span> grades de <span>différenciation</span> selon la surface du contingent solide (<span>&lt; 5%</span>, <span>6-50%</span>, <span>&gt; 50%</span>) et les atypies nucléaires — G1 bien différencié, G2 moyen, G3 peu différencié. <strong><span>Classification</span> moléculaire FIGO 2023</strong> (à connaître) : <span>POLE muté</span> (excellent <span>pronostic</span>), <span>MMR-déficient</span> (Lynch — pronostic intermédiaire, immunothérapie), <span>p53 anormal</span> (mauvais pronostic, équivalent type 2), <span>NSMP</span> (no specific molecular profile, intermédiaire) — guide les décisions thérapeutiques.</p></div>"},{"i":"30c5a78fb3e2","n":300,"o":"300-12","u":"Corps — Diagnostic positif","t":"Connaître les circonstances de découverte du cancer du corps utérin","q":"Que retenir concernant les circonstances de découverte du cancer du corps utérin ?","a":"<div class=\"notion-course\"><p>Les <span>métrorragies post-ménopausiques</span> sont le principal mode de révélation (~<span>90%</span> des cas) — toute métrorragie chez une femme ménopausée doit faire <strong>évoquer un cancer de l'endomètre jusqu'à preuve du contraire</strong>. <span class=\"nc-red nc-bold\">Plus la patiente est âgée</span>, plus le risque est élevé.</p><table><thead><tr><th>Signe</th><th>Contexte / Valeur</th></tr></thead><tbody><tr><td><span>Métrorragies post-ménopausiques</span></td><td>~<span>90%</span> des cas — <strong>signe d'appel cardinal</strong></td></tr><tr><td><span>Ménométrorragies</span> chez la femme non ménopausée</td><td><span>20-30%</span> — plus difficile à interpréter (DD : myome, hyperplasie sans atypie, polype)</td></tr><tr><td><span><span class=\"nc-blue_bg\">Hydrorrhée</span></span></td><td>Écoulement séreux clair, abondant — fréquent</td></tr><tr><td><span><span class=\"nc-blue_bg\">Pyorrhée</span></span></td><td>Rare, mais chez la femme âgée doit <strong>toujours faire évoquer un cancer</strong> de l'endomètre</td></tr><tr><td>Signes de <span>compression</span> (dysurie, <span>constipation</span>)</td><td>Utérus volumineux, <span><span class=\"nc-red nc-bold\">stade</span></span><span class=\"nc-red nc-bold\"> avancé</span></td></tr><tr><td><span>Découverte fortuite</span></td><td>Sur pièce d'hystérectomie pour autre indication, ou écho/<span>IRM</span> pour autre motif révélant un endomètre suspect</td></tr></tbody></table><p><span>Vigilance Lynch</span> : devant des métrorragies chez une femme jeune (&lt; 50 ans) avec ATCD familiaux côlon/endomètre/ovaire, évoquer systématiquement un <span class=\"nc-red_bg\">syndrome de Lynch</span>.</p></div>"},{"i":"e3935b2f52d4","n":300,"o":"300-14","u":"Corps — Examens complémentaires","t":"Connaître la stratégie d'exploration par imagerie d'une tumeur du corps utérin","q":"Que retenir concernant la stratégie d'exploration par imagerie d'une tumeur du corps utérin ?","a":"<div class=\"notion-course\"><ul><li>Métrorragies postménopausiques : examen gynécologique et échographie endovaginale avec mesure et description de l’endomètre ; prélèvement endométrial selon le contexte.</li><li>Un endomètre fin (repère ≤ 4 mm dans une situation appropriée) réduit la probabilité de cancer, mais n’annule pas le besoin d’exploration si saignement persistant/récidivant, facteurs de risque ou image mal analysable.</li><li>Endomètre épaissi, aspect suspect, prélèvement insuffisant ou symptômes persistants : histologie, souvent par <span class=\"nc-blue_bg\">hystéroscopie</span> avec biopsie ciblée selon l’équipe. Une biopsie aveugle négative ne suffit pas si la suspicion reste forte.</li><li>Après confirmation histologique : IRM pelvienne pour extension locale et examens d’extension adaptés au risque, puis discussion en RCP. La TDM thoraco-abdomino-pelvienne recherche les extensions à distance selon indication.</li><li>La classification historique en types I/II et les stades purement anatomiques ont des limites : l’histologie, le grade et le profil moléculaire participent désormais à la stratification thérapeutique.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d941816399facaf545a5cdb8?pvs=204","reviewedAt":"2026-10-15","note":"Cours personnel, couleurs des passages Notion correspondants, corrections et parcours interactifs sourcés. Les compléments sont distingués des figures d’origine."},"liensGlobaux":[{"href":"https://cego-obgyn.fr/deuxieme-cycle/","label":"Collège CNGOF–CEGO · Référentiel, 6e édition 2024"},{"href":"https://jefaismondepistage.cancer.fr/cancer-du-col-de-l-uterus/","label":"INCa · Dépistage du col de l’utérus"},{"href":"https://www.ameli.fr/assure/actualites/le-vaccin-contre-les-infections-papillomavirus-humains-est-desormais-rembourse-jusqu-26-ans","label":"Assurance maladie · Vaccination HPV jusqu’à 26 ans, 2025"},{"href":"https://cngof.fr/app/uploads/2025/11/Reco20depistage20col20GOFS202025.pdf","label":"CNGOF · Cytologie cervicale anormale, actualisation 2025"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Symptôme ou lésion visible ?","detail":"<ul><li>Métrorragies provoquées/spontanées, leucorrhées ou anomalie du col.</li></ul>","branches":[{"label":"Oui","to":"diagnostic"},{"label":"Non","to":"prevention"}]},{"id":"diagnostic","kind":"decision","label":"Examen puis biopsie de lésion suspecte","detail":"<ul><li>Ne pas se limiter à un frottis de dépistage.</li></ul>","branches":[{"label":"Cancer histologique confirmé","to":"extension"},{"label":"Autre résultat","to":"specialiste"}]},{"id":"extension","kind":"finish","label":"Bilan d’extension, notamment IRM pelvienne","detail":"<ul><li>Stade et prise en charge en réunion multidisciplinaire.</li></ul>","branches":[]},{"id":"specialiste","kind":"finish","label":"Conduite selon histologie et concordance","detail":"<ul><li>Une discordance clinique/histologique doit être résolue.</li></ul>","branches":[]},{"id":"prevention","kind":"decision","label":"Vaccination et dépistage organisé","detail":"<ul><li>Rôle HPV, épidémiologie et cofacteurs ; vaccination ne supprime pas le dépistage.</li></ul>","branches":[{"label":"25–29 ans","to":"cytologie"},{"label":"30–65 ans","to":"hpv"},{"label":"Hors cadre standard","to":"adapte"}]},{"id":"cytologie","kind":"finish","label":"Cytologie selon calendrier","detail":"<ul><li>Deux examens normaux à un an, puis intervalle de trois ans.</li></ul>","branches":[]},{"id":"hpv","kind":"finish","label":"Test HPV-HR selon calendrier","detail":"<ul><li>Utiliser le parcours du test HPV positif ; intervalle de cinq ans si négatif.</li></ul>","branches":[]},{"id":"adapte","kind":"finish","label":"Adapter aux antécédents et à l’immunité","detail":"<ul><li>Pas de simple extrapolation du dépistage standard.</li></ul>","branches":[]}]}};
